def config_value(text: str, key: str) -> str:
    """Return the value bound to ``key`` in ``name=value`` config text.

    ``text`` is parsed line by line. Each line is split on the first ``=``;
    whitespace around the name and the value is stripped. Blank lines and
    lines whose first non-space character is ``#`` are ignored, as are lines
    with no ``=``. Returns an empty string when ``key`` is not present.
    The function takes its input only from ``text`` and never reads files.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_config_value_basic() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_config_value_missing_key_returns_empty() -> None:
    assert config_value("host=localhost", "port") == ""


def test_config_value_empty_text() -> None:
    assert config_value("", "host") == ""


def test_config_value_strips_whitespace() -> None:
    assert config_value("  host  =  localhost  ", "host") == "localhost"


def test_config_value_splits_on_first_equals() -> None:
    assert config_value("expr=a=b=c", "expr") == "a=b=c"


def test_config_value_ignores_comments_and_blank_lines() -> None:
    text = "# port=1\n\n   \nport=2"
    assert config_value(text, "port") == "2"


def test_config_value_ignores_lines_without_equals() -> None:
    assert config_value("just some text\nname=x", "name") == "x"
    assert config_value("just some text", "just some text") == ""


def test_config_value_key_match_is_exact() -> None:
    assert config_value("hostname=a", "host") == ""
    assert config_value("Host=a", "host") == ""
